sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var P = 'x_2056099_indust_0_';
    var custASysId = '{{step['a757249cb75e4abeb49077fe0b902191'].record_id}}';
    var custBSysId = '{{step['f7286a5988df4477a0840917e3c32486'].record_id}}';
    var orderA = '', orderB = '', itemA = '', itemB = '';
    try {
        var grOA = new GlideRecord(P + 'cust_order');
        grOA.initialize(); grOA.setValue('customer', custASysId); grOA.setValue('order_date', new GlideDateTime().getValue()); grOA.setValue('status', 'draft'); grOA.setValue('active', true);
        orderA = grOA.insert();
        var grIA = new GlideRecord(P + 'cust_ord_item');
        grIA.initialize(); grIA.setValue('customer_order', orderA); grIA.setValue('quantity_ordered', 5); grIA.setValue('active', true);
        itemA = grIA.insert();
        var grOB = new GlideRecord(P + 'cust_order');
        grOB.initialize(); grOB.setValue('customer', custBSysId); grOB.setValue('order_date', new GlideDateTime().getValue()); grOB.setValue('status', 'draft'); grOB.setValue('active', true);
        orderB = grOB.insert();
        var grIB = new GlideRecord(P + 'cust_ord_item');
        grIB.initialize(); grIB.setValue('customer_order', orderB); grIB.setValue('quantity_ordered', 3); grIB.setValue('active', true);
        itemB = grIB.insert();
        var grQA = new GlideRecord(P + 'cust_order'); grQA.addQuery('customer', custASysId); grQA.query();
        var cA = 0, seenB = false;
        while (grQA.next()) { cA++; if (grQA.getValue('customer') == custBSysId) seenB = true; }
        assertEqual({ name: 'A sees own orders', shouldbe: true, value: cA >= 1 });
        assertEqual({ name: 'A not see B orders', shouldbe: false, value: seenB });
        var grQB = new GlideRecord(P + 'cust_order'); grQB.addQuery('customer', custBSysId); grQB.query();
        var cB = 0, seenA = false;
        while (grQB.next()) { cB++; if (grQB.getValue('customer') == custASysId) seenA = true; }
        assertEqual({ name: 'B sees own orders', shouldbe: true, value: cB >= 1 });
        assertEqual({ name: 'B not see A orders', shouldbe: false, value: seenA });
        var grItemsA = new GlideRecord(P + 'cust_ord_item'); grItemsA.addQuery('customer_order.customer', custASysId); grItemsA.query();
        var iA = 0; while (grItemsA.next()) iA++;
        assertEqual({ name: 'A items scoped', shouldbe: true, value: iA >= 1 });
        var grItemsB = new GlideRecord(P + 'cust_ord_item'); grItemsB.addQuery('customer_order.customer', custBSysId); grItemsB.query();
        var iB = 0; while (grItemsB.next()) iB++;
        assertEqual({ name: 'B items scoped', shouldbe: true, value: iB >= 1 });
        var grU = new GlideRecord(P + 'cust_order'); grU.addQuery('sys_id', orderA); grU.addQuery('customer', custBSysId); grU.query();
        assertEqual({ name: 'Unauthorized access blocked', shouldbe: false, value: grU.hasNext() });
        stepResult.setOutputMessage('Isolation: A=' + cA + ' B=' + cB + ' passed');
    } finally {
        if (itemA) { var d1 = new GlideRecord(P + 'cust_ord_item'); if (d1.get(itemA)) d1.deleteRecord(); }
        if (itemB) { var d2 = new GlideRecord(P + 'cust_ord_item'); if (d2.get(itemB)) d2.deleteRecord(); }
        if (orderA) { var d3 = new GlideRecord(P + 'cust_order'); if (d3.get(orderA)) d3.deleteRecord(); }
        if (orderB) { var d4 = new GlideRecord(P + 'cust_order'); if (d4.get(orderB)) d4.deleteRecord(); }
    }
    return true;
})(outputs, steps, params, stepResult, assertEqual);
